"""Signed install/rollback tests use only temporary plugin copies and test keys."""
import base64
import json
import shutil
import sys
import tempfile
import unittest
import uuid
import zipfile
from pathlib import Path
from unittest.mock import patch

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
import lingyun_update_core as core
import lingyun_update as updater
from tools.build_release import sign


class UpdateTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        # Disposable key generated by Windows .NET; never production signing material.
        import subprocess
        script = "$r=[Security.Cryptography.RSA]::Create(2048);$k=$r.ExportParameters($true);@{n=[Convert]::ToHexString($k.Modulus);d=[Convert]::ToHexString($k.D);e=65537}|ConvertTo-Json -Compress"
        cls.key = json.loads(subprocess.check_output(['pwsh', '-NoProfile', '-Command', script], text=True))

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name) / 'plugin'
        self.root.mkdir()
        for p in ROOT.rglob('*'):
            name = p.relative_to(ROOT).as_posix()
            if p.is_file() and core.code_name(name):
                target = self.root / name
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(p, target)
        core.write_json(self.root / 'lingyun_update_public.json', {k:self.key[k] for k in ('n','e')})
        state = patch.dict('os.environ', {'LOCALAPPDATA': str(Path(self.tmp.name) / 'state')})
        state.start(); self.addCleanup(state.stop)
        self.job_id = uuid.uuid4().hex
        self.job = core.job_dir(self.root, self.job_id)
        self.job.mkdir(parents=True)

    def package(self, change=None):
        files = {p.relative_to(self.root).as_posix():p.read_bytes() for p in self.root.rglob('*') if p.is_file() and core.code_name(p.relative_to(self.root).as_posix())}
        meta = json.loads(files['plugin.json']); meta['version'] = '4.1.0'
        files['plugin.json'] = json.dumps(meta).encode()
        files['lingyun_features/mapper.py'] += b'\n# next version\n'
        if change: change(files)
        with zipfile.ZipFile(self.job / 'package.zip', 'w') as z:
            for name, data in files.items(): z.writestr('plugin/' + name, data)
        archive = (self.job / 'package.zip').read_bytes()
        manifest = dict(schema=1,product=core.PRODUCT,version='4.1.0',archive_root='plugin',
            url=f'https://github.com/{core.REPOSITORY}/releases/download/v4.1.0/lingyun-toolkit-4.1.0.zip',
            size=len(archive),sha256=core.digest(archive),files={n:core.digest(d) for n,d in files.items()})
        raw = json.dumps(manifest).encode()
        (self.job/'update.json').write_bytes(raw)
        (self.job/'update.sig').write_bytes(sign(raw,self.key))
        return manifest

    def test_signed_install_preserves_personal_data_and_clears_nested_cache(self):
        (self.root/'config.json').write_text('personal')
        (self.root/'license.dat').write_text('activation')
        cache=self.root/'lingyun_features/__pycache__/mapper.cpython-312.pyc'
        cache.parent.mkdir(); cache.write_bytes(b'stale')
        self.package()
        self.assertEqual(core.install(self.root,self.job_id),'4.1.0')
        self.assertEqual((self.root/'config.json').read_text(),'personal')
        self.assertEqual((self.root/'license.dat').read_text(),'activation')
        self.assertFalse(cache.exists())

    def test_failed_install_restores_original_bytes(self):
        before={p.relative_to(self.root):p.read_bytes() for p in self.root.rglob('*') if p.is_file()}
        self.package()
        def fail(name):
            if name=='lingyun_features/mapper.py': raise OSError('simulated disk failure')
        with self.assertRaisesRegex(OSError,'simulated'): core.install(self.root,self.job_id,after_replace=fail)
        for name,data in before.items(): self.assertEqual((self.root/name).read_bytes(),data,name)
        self.assertFalse((core.state_dir(self.root)/'transaction.json').exists())

    def test_signature_and_archive_tampering_rejected(self):
        manifest=self.package()
        raw=(self.job/'update.json').read_bytes()
        sig=(self.job/'update.sig').read_bytes()
        public=core.read_json(self.root/'lingyun_update_public.json')
        with self.assertRaises(ValueError): core.verify_manifest(raw+b' ',sig,public)
        with (self.job/'package.zip').open('ab') as f:f.write(b'tampered')
        with self.assertRaises(ValueError): core.unpack(self.root,self.job,manifest)

    def test_reject_paths_changed_keys_and_bootstrap(self):
        for name in ('../bad.py','ui/../../bad.py','config.json','license.dat','lingyun_features/license.dat','ui\\bad.js','/main.py'):
            self.assertFalse(core.code_name(name),name)
        for name in ('main.py','lingyun_features/license_public.json'):
            manifest=self.package(lambda files: files.__setitem__(name,files[name]+b'\n'))
            with self.assertRaises(ValueError): core.unpack(self.root,self.job,manifest)

    def test_reject_downgrade(self):
        self.package()
        meta=core.read_json(self.root/'plugin.json');meta['version']='4.1.0';core.write_json(self.root/'plugin.json',meta)
        with self.assertRaisesRegex(ValueError,'不高于'): core.install(self.root,self.job_id)

    def test_interrupted_transaction_recovers_on_next_start(self):
        original=(self.root/'lingyun_features/mapper.py').read_bytes()
        self.package()
        def crash(name):
            if name=='lingyun_features/mapper.py':raise SystemExit('simulated interruption')
        with self.assertRaises(SystemExit):core.install(self.root,self.job_id,after_replace=crash)
        self.assertTrue((core.state_dir(self.root)/'transaction.json').exists())
        self.assertTrue(core.recover(self.root))
        self.assertEqual((self.root/'lingyun_features/mapper.py').read_bytes(),original)
        self.assertEqual(core.current_version(self.root),'4.0.1')

    def test_helper_waits_for_plugin_lease_then_installs(self):
        import subprocess
        import time
        self.package()
        lease=core.FileLock(core.state_dir(self.root)/'leases/test.lock').acquire()
        process=subprocess.Popen([sys.executable,str(ROOT/'lingyun_update_helper.py'),
            '--root',str(self.root),'--job',self.job_id,'--no-notify'],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        try:
            deadline=time.monotonic()+10
            while not (self.job/'helper-ready.json').exists() and time.monotonic()<deadline:time.sleep(.03)
            self.assertTrue((self.job/'helper-ready.json').exists())
            self.assertIsNone(process.poll())
            self.assertEqual(core.current_version(self.root),'4.0.1')
            lease.close()
            out,err=process.communicate(timeout=15)
            self.assertEqual(process.returncode,0,err)
            self.assertEqual(core.current_version(self.root),'4.1.0')
            self.assertEqual(core.read_json(core.state_dir(self.root)/'status.json')['state'],'done')
        finally:
            lease.close()
            if process.poll() is None:process.kill();process.communicate()

    def test_history_and_numeric_version_order(self):
        notes=updater.release_notes('## V1.10.0\nnew\n## V1.9.0\nold')
        self.assertEqual(list(sorted(notes,key=core.version,reverse=True)),['1.10.0','1.9.0'])
        manager=updater.Manager(self.root)
        self.assertEqual(manager.history()['4.0.0'].splitlines()[0],'- 由于原更新签名私钥丢失，轮换实用插件大全自动更新签名密钥并更新内置公钥。')
        with patch.object(manager,'_begin',return_value={'state':'checking'}) as begin:
            manager.session['checked']=True
            manager.begin(automatic=True)
            begin.assert_not_called()

    def test_background_network_failure_finishes_with_retry_message(self):
        import time
        manager=updater.Manager(self.root)
        with patch.object(manager,'latest',side_effect=ValueError('连接 GitHub 失败')):
            manager.begin()
            deadline=time.monotonic()+5
            while manager.status().get('running') and time.monotonic()<deadline:time.sleep(.02)
        status=manager.status()
        self.assertEqual(status['state'],'error')
        self.assertFalse(status['running'])
        self.assertIn('连接 GitHub 失败',status['message'])


if __name__=='__main__':unittest.main()
